INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('mbe_1179', 'mbe', '1179', '919', '1998', 'CONST. LAW', '186', '', 'Senator makes a speech on the floor of the United States Senate in which she asserts that William, a federal civil servant with minor responsibilities, was twice convicted of fraud by the courts of State X. In making this assertion, Senator relied wholly on research done by Frank, her chief legislative assistant. In fact, it was a different man named William and not William the civil servant, who was convicted of these crimes in the state court proceedings. This mistake was the result of carelessness on Frank''s part. No legislation affecting the appointment or discipline of civil servants or the program of the federal agency for which William works was under consideration at the time Senator made her speech about William on the floor of the Senate. William sues Senator and Frank for defamation. Both defendants move to dismiss the complaint. As a matter of constitutional law, the court hearing this motion should', 'grant it as to Frank, because he is protected by the freedom of speech guarantee against defamation actions by government officials based on his mere carelessness; but deny it as to Senator, because, as an officer of the United States, she is a constituent part of the government and, therefore, has no freedom of speech rights in that capacity.', 'grant it as to both defendants, because Senator is immune to suit for any speech she makes in the Senate under the speech or debate clause of Article I, Section 6, and Frank may assert Senator''s immunity for his assistance to her in preparing the speech.', 'deny it as to both defendants, because any immunity of Senator under the speech or debate clause does not attach to a speech that is not germane to pending legislative business, and Frank is entitled to no greater immunity than the legislator he was assisting.', 'deny it as to Frank, because he is not a legislator protected by the speech or debate clause; but grant it as to Senator, because she is immune from suit for her speech by virtue of that clause.', 'B', 'Article I, Section 6, clause 1 of the Constitution reads, in part,
[Senators and Representatives] shall in all Cases, except Treason, Felony and Breach of the Peace, be privileged … for any Speech or Debate in either House, they shall not be questioned in any other Place1
The Speech or Debate Clause protects the questioning of a Congressman and provides that a member of either house shall not be questioned anywhere other than the House or Senate. The purpose of the Speech or Debate Clause is to preserve and protect the integrity and independence of the legislative process.', 'mbe_897', 0, '186'),
('mbe_1181', 'mbe', '1181', '921', '1998', 'CRIM. LAW', '188', '', 'Smart approached Johnson and inquired about hiring someone to kill his girlfriend''s parents. Unknown to Smart, Johnson was an undercover police officer who pretended to agree to handle the job and secretly taped subsequent conversations with Smart concerning plans and payment. A few days before the payment was due, Smart changed his mind and called the plan off. Nevertheless, Smart was charged with solicitation to commit murder. Smart should be', 'acquitted, because he withdrew before payment and commission of the act.', 'acquitted, because no substantial acts were performed.', 'convicted, because the offense was completed before his attempt to withdraw.', 'convicted, because Johnson agreed to commit the offense.', 'C', 'The crime of solicitation is complete when the solicitation is made, i.e., when the soliciting message is received by its intended recipient. It is immaterial that the object of the solicitation is never consummated, or *461 that no steps are taken towards its completion. (People v. Cook (1984) 151 Cal.App.3d 1142, 1145, 199 Cal.Rptr. 269.)', 'mbe_898', 0, '188'),
('mbe_1182', 'mbe', '1182', '922', '1998', 'CONTRACTS', '189', '', 'Retailer, a dry goods retailer, telephoned Manufacturer, a towel manufacturer, and offered to buy for $5 each a minimum of 500 and a maximum of 1,000 large bath towels, to be delivered in 30 days. Manufacturer orally accepted this offer and promptly sent the following letter to Retailer, which Retailer received two days later: "This confirms our agreement today by telephone to sell you 500 large bath towels for 30-day delivery. /s/ Manufacturer." Twenty-eight days later, Manufacturer tendered to Retailer 1,000 (not 500) conforming bath towels, all of which Retailer rejected because it had found a better price term from another supplier. Because of a glut in the towel market, Manufacturer cannot resell the towels except at a loss. In a suit by Manufacturer against Retailer, which of the following will be the probable decision?', 'Manufacturer can enforce a contract for 1,000 towels, because Retailer ordered and Manufacturer tendered that quantity.', 'Manufacturer can enforce a contract for 500 towels, because Manufacturer''s letter of confirmation stated that quantity term.', 'There is no enforceable agreement, because Retailer never signed a writing.', 'There is no enforceable agreement, because Manufacturer''s letter of confirmation did not state a price term.', 'B', 'Price is another essential term of a contract, without which there cannot be an enforceable contract. Alligood v. Procter & Gamble, Co., 72 Ohio App.3d 309, 311, 594 N.E.2d 668 (1st Dist.1991).', 'mbe_899', 0, '189'),
('mbe_1183', 'mbe', '1183', '923', '1998', 'CONST. LAW', '190', '', 'Doctor, a resident of the city of Greenville in the state of Green, is a physician licensed to practice in both Green and the neighboring state of Red. Doctor finds that the most convenient place to treat her patients who need hospital care is in the publicly owned and operated Redville Municipal Hospital of the city of Redville in the state of Red, which is located just across the state line from Greenville. For many years Doctor had successfully treated her patients in that hospital. Early this year she was notified that she could no longer treat patients in the Redville hospital because she was not a resident of Red, and a newly adopted rule of Redville Municipal Hospital, which was adopted in conformance with all required procedures, stated that every physician who practices in that hospital must be a resident of Red. Which of the following constitutional provisions would be most helpful to Doctor in an action to challenge her exclusion from the Redville hospital solely on the basis of this hospital rule?', 'The bill of attainder clause.', 'The privileges and immunities clause of Article IV.', 'The due process clause of the Fourteenth Amendment.', 'The ex post facto clause.', 'B', 'Article IV, § 2, clause 1 of the Constitution [. . .] provides: “The Citizens of each State shall be entitled to all Privileges and Immunities of Citizens in the several States.” This clause “was designed to insure to a citizen of State A who ventures into State B the same privileges which the citizens of State B enjoy” there. Toomer v. Witsell, 334 U.S. 385, 395, 68 S.Ct. 1156, 92 L.Ed. 1460 (1948). The Supreme Court has accordingly relied upon the Privileges and Immunities Clause to invalidate state laws that favor residents over nonresidents. The Court has developed a “two-step inquiry” to determine whether “a citizenship or residency classification” violates the Privileges and Immunities Clause. Friedman, 487 U.S. at 64, 108 S.Ct. 2260. First, the classification must burden an activity that is “sufficiently basic to the livelihood of the Nation” because “[o]nly with respect to those ‘privileges'' and ‘immunities'' bearing upon the vitality of the Nation as a single entity must the State treat all citizens, resident and nonresident, equally.” Baldwin v. Fish & Game Comm''n of Mont., 436 U.S. 371, 388, 383, 98 S.Ct. 1852, 56 L.Ed.2d 354 (1978). Second, “if the challenged restriction deprives nonresidents of a protected privilege,” then the Court will invalidate the restriction if it “is not closely related to the advancement of a substantial state interest.” Friedman, 487 U.S. at 65, 108 S.Ct. 2260.', 'mbe_900', 0, '190'),
('mbe_1184', 'mbe', '1184', '924', '1998', 'REAL PROP.', '191', '', 'Martin, the owner in fee simple of Orchardacres, mortgaged Orchardacres to Marie to secure the payment of the loan she made to him. The loan was due at the end of the growing season of the year in which it was made. Martin maintained and operated an orchard on the land, which was his sole source of income. Halfway through the growing season, Martin experienced severe health and personal problems and, as a result, left the state; his whereabouts were unknown. Marie learned that no one was responsible for the cultivation and care of the orchard on Orchardacres. She undertook to provide, through employees, the care of the orchard and the harvest for the remainder of the growing season. The net profits were applied to the debt secured by the mortgage on Orchardacres. During the course of the harvest, Paul, a business invitee, was injured by reason of a fault in the equipment used. Under applicable tort case law, the owner of the premises would be liable for Paul''s injuries. Paul brought an appropriate action against Marie to recover damages for the injuries suffered, relying on this aspect of tort law. In such lawsuit, judgment should be for', 'Paul, if, but only if, the state is a title theory state, because in other jurisdictions a mortgagee has no title interest but only a lien.', 'Paul, because Marie was a mortgagee in possession.', 'Marie, because she acted as agent of the owner only to preserve her security interest.', 'Marie, if, but only if, the mortgage expressly provided for her taking possession in the event of danger to her security interest.', 'B', 'A mortgagee may become a mortgagee in possession where the mortgage itself gives the mortgagee the right to enter and “take possession of the mortgaged premises and receive the rents and profits” (Gomez v. Bobker, 124 A.D.2d 703, 704, 508 N.Y.S.2d 215; see e.g. Gasco Corp. & Gordian Group of Hong Kong v. Tosco Props., 236 A.D.2d 510, 653 N.Y.S.2d 687). A mortgagee in possession “takes the rents and profits in the quasi character of trustee or bailiff of the mortgagor” (Gasco Corp. & Gordian Group of Hong Kong v. Tosco Props., 236 A.D.2d at 512, 653 N.Y.S.2d 687 [internal quotation marks omitted]).
“[A] mortgagee cannot be in possession without consent of the mortgagor” (Hoye v. Theresa, 134 App.Div. 255, 256, 118 N.Y.S. 951; see Gordon v. Krellman, 207 App.Div. 773, 202 N.Y.S. 682). “In order to acquire the rights of a mortgagee in possession it [is] necessary for the [party claiming such status] to show that it had entered with the mortgagor''s consent, or had otherwise entered lawfully” (Herrmann v. Cabinet Land Co., 217 N.Y. 526, 528, 112 N.E. 476).', 'mbe_901', 0, '191'),
('mbe_1185', 'mbe', '1185', '925', '1998', 'TORTS', '192', '', 'Actor, a well-known movie star, was drinking Vineyard wine at a nightclub. A bottle of the Vineyard wine, with its label plainly showing, was on the table in front of Actor. An amateur photographer asked Actor if he could take his picture and Actor said, "Yes." Subsequently, the photographer sold the photo to Vineyard. Vineyard, without Actor''s consent, used the photo in a wine advertisement in a nationally circulated magazine. The caption below the photo stated, "Actor enjoys his Vineyard wine." If Actor sues Vineyard to recover damages as a result of Vineyard''s use of the photograph, will Actor prevail?', 'No, because Actor consented to being photographed.', 'No, because Actor is a public figure.', 'Yes, because Vineyard made commercial use of the photograph.', 'Yes, unless Actor did, in fact, enjoy his Vineyard wine.', 'C', 'A claim for a violation of a right to publicity under Georgia law protects against “the appropriation of another''s name and likeness ... without consent and for the financial gain of the appropriator ... whether the person whose name and likeness is used is a private citizen, entertainer, or ... a public figure who is not a public official.” Toffoloni v. LFP Publ''g Group, LLC, 572 F.3d 1201, 1205 (11th Cir.2009) (quoting Martin Luther King, Jr., Ctr. for Soc. Change, Inc., 250 Ga. at 143, 296 S.E.2d 697). “The right of publicity may be defined as [an individual''s] right to the exclusive use of his or her name and likeness.” Toffoloni, 572 F.3d at 1205 (quoting  Martin Luther King, Jr., Ctr. for Soc. Change, Inc., 250 Ga. at 143, 296 S.E.2d 697). In Georgia, the right of publicity encompasses the “rights of private citizens, as well as entertainers, not to have their names and photographs used for the financial gain of the user without their consent, where such use is not authorized as an exercise of freedom of the press.” Toffoloni, 572 F.3d at 1206 (quoting Martin Luther King, Jr., Ctr. for Soc. Change, Inc., 250 Ga. at 143, 296 S.E.2d 697).', 'mbe_902', 0, '192'),
('mbe_1187', 'mbe', '1187', '927', '1998', 'CONTRACTS', '194', '', 'Buyer mailed a signed order to Seller that read: "Please ship us 10,000 widgets at your current price." Seller received the order on January 7 and that same day mailed to Buyer a properly stamped, addressed, and signed letter stating that the order was accepted at Seller''s current price of $10 per widget. On January 8, before receipt of Seller''s letter, Buyer telephoned Seller and said, "I hereby revoke my order." Seller protested to no avail. Buyer received Seller''s letter on January 9. Because of Buyer''s January 8 telephone message, Seller never shipped the goods. Under the relevant and prevailing rules, is there a contract between Buyer and Seller as of January 10?', 'No, because the order was an offer that could be accepted only by shipping the goods; and the offer was effectively revoked before shipment.', 'No, because Buyer never effectively agreed to the $10 price term.', 'Yes, because the order was, for a reasonable time, an irrevocable offer.', 'Yes, because the order was an offer that seller effectively accepted before Buyer attempted to revoke it.', 'D', 'Once the offer of dedication is made, it must be accepted to be effective. Rowe v. Durham, 235 N.C. 158, 161, 69 S.E.2d 171, 173 (1952). In the case of a municipality, the acceptance must take place in some legally recognized form, either expressly by a resolution, order, or formal ratification, or impliedly by use and control of the area by public authorities for a period of 20 years or more. Bumgarner, 105 N.C.App. at 366–67, 413 S.E.2d at 569, modified and aff''d., 332 N.C. 624, 422 S.E.2d 686 (1992).  An offer of dedication can be revoked at any time prior to acceptance, but once acceptance is made, it becomes irrevocable. Cavin v. Ostwalt, 76 N.C.App. 309, 312, 332 S.E.2d 509, 511 (1985); Rowe v. Durham, 235 N.C. 158, 160, 69 S.E.2d 171, 172 (1952).', 'mbe_903', 0, '194'),
('mbe_1188', 'mbe', '1188', '928', '1998', 'TORTS', '195', '', 'As Seller, an encyclopedia salesman, approached the grounds on which Hermit''s house was situated, he saw a sign that said, "No salesmen. Trespassers will be prosecuted. Proceed at your own risk." Although Seller had not been invited to enter, he ignored the sign and drove up the driveway toward the house. As he rounded a curve, a powerful explosive charge buried in the driveway exploded, and Seller was injured. Can Seller recover damages from Hermit for his injuries?', 'Yes, if Hermit was responsible for the explosive charge under the driveway.', 'Yes, unless Hermit, when he planted the charge, intended only to deter, not to harm, a possible intruder.', 'No, because Seller ignored the sign, which warned him against proceeding further.', 'No, if Hermit reasonably feared that intruders would come and harm him or his family.', 'A', 'Thus, a landowner''s duty with respect to a trespasser is twofold: (1) the landowner may not use his land in such a way that he deliberately or maliciously causes injury to a trespasser, and (2) once the landowner is aware of the presence of a trespasser, the landowner must use reasonable care to avoid injuring the trespasser. See generally Webster''s Third New International Dictionary 2575 (defining “wanton”), 2617 (defining “willful”). A “trespasser” is one who has no legal right to be upon another''s land and enters the land without the express or implied consent of the owner. Reasoner v. Chicago, Rock Island & Pac. R.R., 251 Iowa 506, 510, 101 N.W.2d 739, 741 (1960); Mann, 232 Iowa at 1056, 7 N.W.2d at 50.', 'mbe_409', 0, '195'),
('mbe_1189', 'mbe', '1189', '929', '1998', 'REAL PROP.', '196', '', 'Adam owned Blackacre. Adam entered into a written three-year lease of Blackacre with Bertha. Among other provisions, the lease prohibited Bertha from "assigning this lease, in whole or in part, and from subletting Blackacre, in whole or in part." In addition to a house, a barn, and a one-car garage, Blackacre''s 30 acres included several fields where first Adam, and now Bertha, grazed sheep. During the following months, Bertha: I. By a written agreement allowed her neighbor Charles exclusive use of the garage for storage, under lock and key, of his antique Packard automobile for two years, charging him $240. II. Told her neighbor Doris that Doris could use the fields to practice her golf as long as she did not disturb Bertha''s sheep. Which, if any, of Bertha''s actions constituted a violation of the lease?', 'I only.', 'II only.', 'Both I and II.', 'Neither I nor II.', 'A', '“A lease is both a contract and a conveyance.” K.F. Boackle, Mississippi Landlord and Tenant Law with Forms § 1.2 (2005).  As a contract, a lease is freely assignable unless a provision in the lease expressly states the contrary. See Jeffery Jackson & Mary Miller, Encyclopedia of Mississippi Law § 21:33 (2015).', 'mbe_904', 0, '196'),
('mbe_1190', 'mbe', '1190', '930', '1998', 'CRIM. LAW', '197', '', 'Defendant is charged with murder. The evidence shows that she pointed a gun at Victim and pulled the trigger. The gun discharged, killing Victim. The gun belonged to Victim. Defendant testifies that Victim told her, and she believed, that the "gun" was a stage prop that could fire only blanks, and that she fired the gun as part of rehearsing a play with Victim at his house. If the jury believes Defendant''s testimony and finds that her mistaken belief that the gun was a prop was reasonable, they should find her', 'guilty of murder.', 'guilty of manslaughter.', 'guilty of either murder or manslaughter.', 'not guilty of murder or manslaughter.', 'D', '“When an accused creates an issue of mistaken belief as to the culpable mental element of the offense, he is entitled to a defensive instruction of ‘mistake of fact.’ ” Miller, 815 S.W.2d at 585. Therefore, in the instant case, the issue before the trial court was whether appellant''s purported belief, if accepted as true, negated the culpability required for murder. See, e.g., Hill v. State, 765 S.W.2d 794, 796 (Tex.Crim.App.1989) (holding appellant was entitled to instruction on mistake of fact when mistake negated culpability required for the offense). Clearly, it does.', 'mbe_905', 0, '197'),
('mbe_1191', 'mbe', '1191', '931', '1998', 'TORTS', '198', '', 'Del''s sporting goods shop was burglarized by an escaped inmate from a nearby prison. The inmate stole a rifle and bullets from a locked cabinet. The burglar alarm at Del''s shop did not go off because Del had negligently forgotten to activate the alarm''s motion detector. Shortly thereafter, the inmate used the rifle and ammunition stolen from Del in a shooting spree that caused injury to several people, including Paula. If Paula sues Del for the injury she suffered, will Paula prevail?', 'Yes, if Paula''s injury would have been prevented had the motion detector been activated.', 'Yes, because Del was negligent in failing to activate the motion detector.', 'No, because the storage and sale of firearms and ammunition is not an abnormally dangerous activity.', 'No, unless there is evidence of circumstances suggesting a high risk of theft and criminal use of firearms stocked by Del.', 'D', 'As a result of the need to comply with statutory licensing requirements and the regulations mandated by the New Jersey Administrative Code, it is reasonable to conclude that Adventure Sport was well aware of the grave risk of danger if criminals, or any other unauthorized persons, gained access to its guns. In somewhat similar circumstances, other business owners and landlords have been required to protect customers and tenants from foreseeable criminal acts occurring on their premises even though the criminal conduct was beyond their control. “If the reasonably prudent person would foresee danger resulting from another''s voluntary criminal acts, the fact that another''s actions are beyond defendant''s control does not preclude liability.” In Trentacost v. Brussel, 82 N.J. 214, 412 A.2d 436 (1980), a tenant was assaulted on the stairway leading to her apartment. Id. at 218, 412 A.2d 436. There was no lock on the front door and there was evidence that criminal activity affecting the building was reasonably foreseeable. Ibid. The Court determined that the landlord had “a legal duty to take reasonable security measures for tenant protection on the premises” because the criminal conduct was foreseeable. Id. at 231, 412 A.2d 436; see also Wlasiuk v. McElwee, 334 N.J.Super. 661, 667–68, 760 A.2d 829 (App.Div.2000) (driver of motor vehicle liable to passenger injured by criminal act of *433 stranger whom driver allowed into vehicle, because risk of harm from giving rides to strangers was reasonably foreseeable); Ventresco v. Gokvlesh Convenience, 318 N.J.Super. 473, 478, 723 A.2d 1250 (App.Div.1999) (“All that is required is sufficient information to apprise the proprietor of the existence of danger and enough time to act on behalf of the patron''s safety.”); Picco v. Fords Diner, Inc., 113 N.J.Super. 465, 467, 274 A.2d 301 (App.Div.1971) (“Absence of any night illumination of ... parking area might reasonably be considered a dereliction on the part of defendant, which contributed proximately to the criminal assault.... It is common knowledge that lighting an area during nighttime hours deters criminal activity.” **849 ). These decisions imposed liability upon defendants for failure to protect against the criminal propensities of third persons where the likelihood of serious harm could be easily anticipated and the defendants failed to take reasonable measures to prevent the harm.
Public policy considerations are also important when determining whether a duty exists. Plaintiffs argue that because there are thousands of deaths each year from gun violence, there is a strong public need to prevent easy access to firearms. In Kelly v. Gwinnell, 96 N.J. 538, 476 A.2d 1219 (1984), the New Jersey Supreme Court determined that a social host could be liable for injuries to a plaintiff resulting from a drunk driving accident. Id. at 548, 476 A.2d 1219. Chief Justice Wilentz noted that the host could foresee quite clearly that the “continued provision of alcohol to [the driver] was making it more and more likely that [the driver] would not be able to operate his car carefully.” Id. at 544, 476 A.2d 1219. Nevertheless, the primary issue focused on whether the host owed a duty to public users of the highway. Social considerations weighed heavily in the Court''s decision to impose such a duty. “In a society where thousands of deaths are caused each year by drunken drivers ... the imposition of a duty is both consistent with and supportive of a social goal—the reduction of drunk driving....” Id. at 544–45, 476 A.2d 1219. In Kelly, the Court determined that a social host''s liability “proceeds from the duty of care that accompanies control of the liquor supply.” *434 Id. at 548, 476 A.2d 1219. Similarly, Adventure Sport controlled their inventory of handguns and derived a profit from the sale of firearms.', 'mbe_906', 0, '198'),
('mbe_1192', 'mbe', '1192', '932', '1998', 'CONST. LAW', '199', '', 'A statute of the state of Texona prohibits any retailer of books, magazines, pictures, or posters from "publicly displaying or selling to any person any material that may be harmful to minors because of the violent or sexually explicit nature of its pictorial content." Violation of this statute is a misdemeanor. Corner Store displays publicly and sells magazines containing violent and sexually explicit pictures. The owner of this store is prosecuted under the above statute for these actions. In defending against this prosecution in a Texona trial court, the argument that would be the best defense for Corner Store is that the statute violates the', 'First Amendment as it is incorporated into the Fourteenth Amendment, because the statute is excessively vague and overbroad.', 'First Amendment as it is incorporated into the Fourteenth Amendment, because a state may not prohibit the sale of violent or sexually explicit material in the absence of proof that the material is utterly without any redeeming value in the marketplace of ideas.', 'equal protection of the laws clause, because the statute irrationally treats violent and sexually explicit material that is pictorial differently from such material that is composed wholly of printed words.', 'equal protection of the laws clause, because the statute irrationally distinguishes between violent and sexually explicit pictorial material that may harm minors and such material that may harm only adults.', 'A', 'Regulations limiting both protected and unprotected speech must clearly relay what expressive conduct or speech would violate the law. While the vagueness doctrine is an outgrowth of the Due Process Clauses of the Fifth and Fourteenth Amendments, it raises special First Amendment concerns because of its obvious chilling effect on free speech (Reno, 521 U.S. at 872).
The US Constitution does not require perfect clarity and precise guidance, even of regulations that restrict expressive activity. Instead, to determine whether a limitation on speech is unconstitutionally vague, courts consider whether the law:
Fails to provide a person of ordinary intelligence fair notice of what is prohibited.
Is so standardless that it authorizes or encourages seriously discriminatory enforcement.
(United States v. Williams, 553 U.S. 285, 305 (2008).)', 'mbe_907', 0, '199'),
('mbe_1193', 'mbe', '1193', '933', '1998', 'EVIDENCE', '200', '', 'In an arson prosecution the government seeks to rebut Defendant''s alibi that he was in a jail in another state at the time of the fire. The government calls Witness to testify that he diligently searched through all the records of the jail and found no record of Defendant''s having been incarcerated there during the time Defendant specified. The testimony of Witness is', 'admissible as evidence of absence of an entry from a public record.', 'admissible as a summary of voluminous documents.', 'inadmissible, because it is hearsay not within any exception.', 'inadmissible, because the records themselves must be produced.', 'A', 'To prove:
1. The absence of a record, report, statement or data compilation, in any form; or
2. The nonoccurrence or nonexistence of a matter of which a record, report, statement or data compilation, in any form, was regularly made and preserved by a public officer, agency or official,

evidence in the form of a certificate of the custodian or other person authorized to make the certification, or testimony, that diligent search failed to disclose the record, report, statement, data compilation or entry is not inadmissible under the hearsay rule.', 'mbe_908', 0, '200'),
('mbe_1355', 'mbe', '1355', '1095', 'Because the ordinance is not related to the exercise of a fundamental right or based on a suspect trait, it need only rationally relate to some legitimate governmental interest. Under the Equal Protection Clause, which is implicated because the ordinance treats some city employees differently from others, a governmental classification must be necessary to promote a compelling state interest when it relates to who may exercise a fundamental right or when it is based on a suspect trait (e.g., race or national origin). If a quasi-suspect classification (e.g., gender or legitimacy) is involved, the classification will be upheld if it is substantially related to an important government interest. In all other cases, the classification is valid if there is any conceivable basis on which it might relate to any legitimate governmental interest. This "rational basis" test is used for all classifications that relate only to matters of economics or social welfare. The right of police officers and firefighters to hold second jobs is not a fundamental right that will trigger strict scrutiny. In addition, the ordinance is not based on a suspect or quasi-suspect classification. Therefore, the validity of the ordinance is judged according to the "rational basis" test. A party attacking a classification under this test bears the difficult burden of demonstrating to the court that the classification does not have a rational relationship to a legitimate interest of government.', 'CONST. LAW', '6', '', 'A city passed an ordinance prohibiting all of its police officers and firefighters from "moonlighting" (working a second job). The ordinance was passed to ensure that all police officers and firefighters were readily available in case an emergency should arise and for overtime work when the situation warranted it. Other city employees, including members of the city council and the city manager, had no such restrictions placed on secondary employment. A police officer who wanted to moonlight as a dancer at a nightclub within city limits brought suit in federal court, alleging that the ordinance violated her constitutional rights. How should the court rule on the constitutionality of the ordinance?', 'The ordinance is unconstitutional, because it restricts the officer''s First Amendment rights to freedom of expression.', 'The ordinance is unconstitutional, because the singling out of police officers and firefighters violates equal protection.', 'The ordinance is constitutional, because the city has a significant interest that it seeks to regulate.', 'The ordinance is constitutional, because there is a rational basis for the ordinance.', 'D', 'Because the ordinance is not related to the exercise of a fundamental right or based on a suspect trait, it need only rationally relate to some legitimate governmental interest. Under the Equal Protection Clause, which is implicated because the ordinance treats some city employees differently from others, a governmental classification must be necessary to promote a compelling state interest when it relates to who may exercise a fundamental right or when it is based on a suspect trait (e.g., race or national origin). If a quasi-suspect classification (e.g., gender or legitimacy) is involved, the classification will be upheld if it is substantially related to an important government interest. In all other cases, the classification is valid if there is any conceivable basis on which it might relate to any legitimate governmental interest. This "rational basis" test is used for all classifications that relate only to matters of economics or social welfare. The right of police officers and firefighters to hold second jobs is not a fundamental right that will trigger strict scrutiny. In addition, the ordinance is not based on a suspect or quasi-suspect classification. Therefore, the validity of the ordinance is judged according to the "rational basis" test. A party attacking a classification under this test bears the difficult burden of demonstrating to the court that the classification does not have a rational relationship to a legitimate interest of government.', 'mbe_1038', 0, '6'),
('mbe_408', 'mbe', '408', '231', 'MBE-1978-83-part6', '', '8', '', 'A statute of the state of Tuscarora made it a misdemeanor to construct any building of more than five stories without an automatic fire sprinkler system. A local construction company built in Tuscarora a ten-story federal office building. It constructed the building according to the precise specifications of a federal contract authorized by federal statutes. Because the building was built without the automatic fire sprinkler system required by state law, Tuscarora prosecutes the private contractor. Which of the following is the company''s strongest defense to that prosecution?', 'The state sprinkler requirement denies the company property or liberty without due process.', 'The state sprinkler requirement denies the company equal protection of the laws.', 'As applied, the state sprinkler requirement violates the supremacy clause.', 'As applied, the state sprinkler requirement violates the obligation of contracts clause.', 'C', '“The Supremacy Clause, U.S. Const., Art. VI, cl. 2, invalidates state laws that ‘interfere with, or are contrary to,’ federal law.” Qwest Corp. v. Minn. Pub. Utils. Comm''n, 684 F.3d 721, 726 (8th Cir.2012) (citations omitted).  The Supremacy Clause comes into play where, among other situations, “there is an actual conflict between state and federal law” such that “compliance with both federal and state regulations is a physical impossibility ... or when state law stands as an obstacle to the accomplishment and execution of the full purposes and objectives of Congress.” Id. (citations omitted). Federal regulations, like those at issue in this case, have the same preemptive force as federal laws. See Fid. Fed. Sav. & Loan Ass''n v. de la Cuesta, 458 U.S. 141, 153, 102 S.Ct. 3014, 73 L.Ed.2d 664 (1982).', 'mbe_113', 0, '8'),
('mbe_890', 'mbe', '890', '657', '1991-July', 'CONTRACTS', '142', 'On November 15, Joiner in a signed writing contracted with Galley for an agreed price to personally remodel Galley''s kitchen according to specifications provided by Galley, and to start work on December 1. Joiner agreed to provide all materials for the job in addition to all of the labor required.', 'For this question only, assume the following facts. On November 26, Galley without legal excuse repudiated the contract. Notwithstanding Galley''s repudiation, however, Joiner subsequently purchased for $5,000 materials that could only be used in remodeling Galley''s kitchen, and promptly notified Galley, "I will hold you to our contract." If allowed to perform, Joiner would have made a profit of $3,000 on the job. If Galley refuses to retract his repudiation, and Joiner sues him for damages, what is the maximum that Joiner is entitled to recover?', 'Nothing, because he failed to mitigate his damages.', '$3,000, his expectancy damages.', '$5,000, on a restitutionary theory.', '$5,000, his reliance damages, plus $3,000, his expectancy damages.', 'B', 'Expectation damages are recoverable where: (1) “damages were reasonably foreseeable by the breaching party at the time of contracting;” (2) damages were caused by the breach; and (3) “the damages are shown with reasonable certainty.” Ind. Mich. Power Co. v. United States, 422 F.3d 1369, 1373 (Fed.Cir.2005)(citing Energy Capital Corp. v. United States, 302 F.3d 1314, 1320 (Fed.Cir.2002)); see also Bluebonnet Savings Bank, FSB v. United States, 67 Fed.Cl. 231, 235 (2005). These factors, when applied in concert, ensure that a damages award may not be based on mere speculation. See Bluebonnet, 67 Fed.Cl. at 235.', 'mbe_611', 0, '142'),
('mbe_991', 'mbe', '991', '744', '1992', '', '481', 'Three states, East Winnetka, Midland, and West Hampton, are located next to one another in that order. The states of East Winnetka and West Hampton permit the hunting and trapping of snipe, but the state of Midland strictly forbids these activities in order to protect snipe, a rare species of animal, from extinction. The state of Midland has a state statute that provides, "Possession of snipe traps is prohibited. Any game warden finding a snipe trap within the state shall seize and destroy it." Snipe traps cost about $15 each. Prentis is a resident of West Hampton and an ardent snipe trapper. She drove her car to East Winnetka to purchase a new improved snipe trap from a manufacturer there. In the course of her trip back across Midland with the trap in her car, Prentis stopped in a Midland state park to camp for a few nights. While she was in that park, a Midland game warden saw the trap, which was visible on the front seat of her car. The warden seized the trap and destroyed it in accordance with the Midland statute after Prentis admitted that the seized item was a prohibited snipe trap. No federal statutes or federal administrative regulations apply.', 'For this question only, assume that Prentis demonstrates that common carriers are permitted to transport snipe traps as cargo across Midland for delivery to another state and that in practice the Midland statute is enforced only against private individuals transporting those traps in private vehicles. If Prentis challenges the application of the Midland statute to her on the basis only of a denial of equal protection, the application of the statute will probably be found', 'constitutional, because the traps constitute contraband in which Prentis could have no protected property interest.', 'constitutional, because there is a rational basis for differentiating between the possession of snipe traps as interstate cargo by common carriers and the possession of snipe traps by private individuals.', 'unconstitutional, because the state cannot demonstrate a compelling public purpose for making this differentiation between common carriers and such private individuals.', 'unconstitutional, because interstate travel is a fundamental right that may not be burdened by state law.', 'B', '"Dormant" Commerce Clause
The “Dormant Commerce Clause" refers to the prohibition, implicit in the Commerce Clause, against states passing legislation that discriminates against or excessively burdens interstate commerce. Of particular importance here, is the prevention of protectionist state policies that favor state citizens or businesses at the expense of non-citizens conducting business within that state. In West Lynn Creamery Inc. v. Healy, 512 U.S. 186 (1994), the Supreme Court struck down a Massachusetts state tax on milk products, as the tax impeded interstate commercial activity by discriminating against non-Massachusetts', 'mbe_413', 0, '481'),
('mbe_47', 'mbe', '47', '29', 'MBE-1972-78-part2', '', '48', 'An ordinance of City makes it unlawful to park a motor vehicle on a City street within ten feet ofa fire hydrant. At 1:55 p.m. Parker, realizing he must be in Bank before it closed at 2:00 p.m., and finding no other space available, parked his automobile in front of a fire hydrant on a City street. Parker then hurried into the bank, leaving his aged neighbor, Ned, as a passenger in the rear seat of the car. About 5 minutes later, and while Parker was still in Bank, Driver was driving down the street. Driver swerved to avoid what he mistakenly thought was a hole in the street and sideswiped Parker''s car. Parker''s car was turned over on top of the hydrant, breaking the hydrant and causing a small flood of water. Parker''s car was severely damaged and Ned was badly injured. There is no applicable guest statute.', 'If Parker asserts a claim against Driver for damage to Parker''s automobile, the most likely result is that Parker will', 'recover because the purpose of the ordinance is to provide access to the fire hydrant', 'recover because Driver''s negligence was later in time than Parker''s act of parking', 'not recover because Parker was contributorily negligent as a matter of law', 'not recover because Parker''s action in parking unlawfully was a continuing wrong', 'A', 'Kansas courts discussed assumption of risk as early as 1898. See Greef Bros. v. Brown, 7 Kan.App. 394, 51 P. 926 (1898). But in those early cases it was viewed as a “species of contributory negligence.” Greef Bros., 7 Kan.App. at 398, 51 P. 926 (discussing relationship between assumption of risk and contributory negligence). Contributory negligence is defined as “conduct on the part of the plaintiff which falls below the standard to which he should conform for his own protection and which is the legally contributing cause, cooperating with the negligence of the defendant, in bringing about the plaintiff''s harm.” Guerra, 204 Kan. at 313, 461 P.2d 737. Over time, however, this court recognized distinctions between the two doctrines, with contributory negligence seen as arising from tort law, while assumption *306 of risk arose from an implied contract. Guerra, 204 Kan. at 313, 461 P.2d 737.', 'mbe_95', 0, '48'),
('mbe_48', 'mbe', '48', '29', 'MBE-1972-78-part2', '', '49', 'An ordinance of City makes it unlawful to park a motor vehicle on a City street within ten feet ofa fire hydrant. At 1:55 p.m. Parker, realizing he must be in Bank before it closed at 2:00 p.m., and finding no other space available, parked his automobile in front of a fire hydrant on a City street. Parker then hurried into the bank, leaving his aged neighbor, Ned, as a passenger in the rear seat of the car. About 5 minutes later, and while Parker was still in Bank, Driver was driving down the street. Driver swerved to avoid what he mistakenly thought was a hole in the street and sideswiped Parker''s car. Parker''s car was turned over on top of the hydrant, breaking the hydrant and causing a small flood of water. Parker''s car was severely damaged and Ned was badly injured. There is no applicable guest statute.', 'If City asserts a claim against Driver for the damage to the fire hydrant and Driver was negligent in swerving his car, his negligence is', 'a cause in fact and a legal cause of City''s harm', 'a cause in fact, but not a legal cause, of City''s harm because Parker parked illegally', 'a legal cause, but not a cause in fact, of City''s harm because Parker''s car struck the hydrant', 'neither a legal cause nor a cause in fact of City''s harm', 'A', '“Legal cause is established if an injury was foreseeable as the type of harm that a reasonable person would expect to see as a likely result of his or her conduct. [Citation.] Although the foreseeability of an injury will establish legal cause, the extent of the injury or the exact way in which it occurs need not be foreseeable.” Hooper v. County of Cook, 366 Ill.App.3d 1, 7, 303 Ill.Dec. 476, 851 N.E.2d 663, 669 (2006).', 'mbe_58', 0, '49'),
('mbe_72', 'mbe', '72', '45', 'MBE-1972-78-part3', '', '23', 'Price sued Derrick for injuries Price received in an automobile accident. Price claimed Derrick was negligent in (a) exceeding the posted speed limit of 35 m.p.h., (b) failing to keep a lookout, and (c) crossing the center line.', 'Derrick testified in his own behalf that he was going 30 m.p.h. On cross-examination, Price''s counsel did not question Derrick with regard to his speed. Subsequently, Price''s counsel calls Officer to testify that, in his investigation following the accident, Derrick told him he was driving 40 m.p.h. Officer''s testimony is', 'admissible as a prior inconsistent statement', 'admissible as an admission', 'inadmissible, because it lacks a foundation', 'inadmissible, because it is hearsay not within any exception', 'B', 'A statement by a party-opponent is an admission and admissible as an exception to the hearsay rule if it meets the following requirements: (1) a conscious or voluntary acknowledgment by a party-opponent of the existence of certain facts; (2) the matter acknowledged must be relevant to the cause of the party offering the admission; and (3) the matter acknowledged must be unfavorable to, or inconsistent with, the position now taken by the party-opponent. Nettie''s Flower Garden, Inc. v. SIS, Inc., 869 S.W.2d 226, 229 (Mo.App. E.D.1993).', 'mbe_169', 0, '23'),
('mbe_107', 'mbe', '107', '63', 'MBE-1972-78-part4', '', '7', 'Pemberton and three passengers, Able, Baker, and Charley, were injured when their car was struck by a truck owned by Mammoth Corporation and driven by Edwards. Helper, also a Mammoth employee, was riding in the truck. The issues in Pemberton v. Mainmmoth include the negligence of Edwards in driving too fast and failing to wear glasses, and of Pemberton in failing to yield the eight of way.', 'Mammoth''s counsel seeks to have Sheriff testify that while he was investigating the accident he was told by Pemberton, "This was probably our fault." The judge should rule the proffered evidence', 'admissible as an admission of a party', 'admissible, because it is a statement made to a police officer in the course of an official investigation', 'inadmissible, because it is a mixed conclusion of law and fact', 'inadmissible, because it is hearsay, not within any exception', 'A', 'A statement by a party-opponent is an admission and admissible as an exception to the hearsay rule if it meets the following requirements: (1) a conscious or voluntary acknowledgment by a party-opponent of the existence of certain facts; (2) the matter acknowledged must be relevant to the cause of the party offering the admission; and (3) the matter acknowledged must be unfavorable to, or inconsistent with, the position now taken by the party-opponent. Nettie''s Flower Garden, Inc. v. SIS, Inc., 869 S.W.2d 226, 229 (Mo.App. E.D.1993).', 'mbe_169', 0, '7'),
('mbe_597', 'mbe', '597', '393', '1991-Feb', 'CONTRACTS', '44', 'Ohner and Planner signed a detailed writing in which Planner, a landscape architect, agreed to landscape and replant Ohner''s residential property in accordance with a design prepared by Planner and incorporated in the writing. Ohner agreed to pay $10,000 for the work upon its completion. Ohner''s spouse was not a party to the agreement, and had no ownership interest in the premises.', 'For this question only, assume the following facts. Shortly before the agreement was signed, Ohner and Planner orally agreed that the writing would not become binding on either party unless Ohner''s spouse should approve the landscaping design. If Ohner''s spouse disapproves the design and Ohner refuses to allow Planner to proceed with the work, is evidence of the oral agreement admissible in Planner''s action against Ohner for breach of contract?', 'Yes, because the oral agreement required approval by a third party.', 'Yes, because the evidence shows that the writing was intended to take effect only if the approval occurred.', 'No, because the parol evidence rule bars evidence of a prior oral agreement even if the latter is consistent with the terms of a partial integration.', 'No, because the prior oral agreement contradicted the writing by making the parties'' duties conditional.', 'B', '“The parol evidence rule states that, ‘absent fraud, mistake or other invalidating cause, the parties'' final written integration of their agreement may not be varied, contradicted or supplemented by evidence of prior or contemporaneous oral agreements, or prior written agreements.’ ” Galmish v. Cicchini, 90 Ohio St.3d 22, 27, 734 N.E.2d 782 (2000), quoting 11 Williston on Contracts (4 Ed. 1999) 569–570, Section 33:4. “The parol evidence rule is a rule of substantive law that prohibits a party who has entered into a written contract from contradicting the terms of the contract with evidence of alleged or actual agreements.” Provident Bank v. Adriatic, Inc., 12th Dist. No. CA2004–12–108, 2005-Ohio-5774, 2005 WL 2840741, ¶ 17, citing Ed Schory & Sons, Inc. v. Society Nat''l. Bank, 75 Ohio St.3d 433, 440, 662 N.E.2d 1074 (1996).', 'mbe_453', 0, '44'),
('mbe_617', 'mbe', '617', '411', '1991-Feb', 'CONTRACTS', '64', 'Elda, the aged mother of Alice and Barry, both adults, wished to employ a live-in companion so that she might continue to live in her own home. Elda, however, had only enough income to pay one-half of the companion''s $2,000 monthly salary. Learning of their mother''s plight, Alice and Barry agreed with each other in a signed writing that on the last day of January and each succeeding month during their mother''s lifetime, each would give Elda $500. Elda then hired the companion. Alice and Barry made the agreed payments in January, February, and March. In April, however, Barry refused to make any payment and notified Alice and Elda that he would make no further payments.', 'Will Elda succeed in an action for $500 brought against Barry after April 30?', 'Yes, because by making his first three payments, Barry confirmed his intent to contract.', 'Yes, because Elda is an intended beneficiary of a contract between Alice and Barry.', 'No, because a parent cannot sue her child for breach of a promise for support.', 'No, because Alice and Barry intended their payments to Elda to be gifts.', 'B', '“A beneficiary will be considered an intended beneficiary, rather than merely an incidental beneficiary, when the circumstances indicate that the promisee intends to give the beneficiary the benefit of the promised performance” (Tasseff v. Nussbaumer & Clarke, 298 A.D.2d 877, 878, 747 N.Y.S.2d 621 [internal quotation marks omitted]; see Fourth Ocean Putnam Corp., 66 N.Y.2d at 44, 495 N.Y.S.2d 1, 485 N.E.2d 208).', 'mbe_817', 0, '64'),
('mbe_692', 'mbe', '692', '478', '1991-Feb', 'CONTRACTS', '141', '', 'Fruitko, Inc., ordered from Orchard, Inc., 500 bushels of No. 1 Royal Fuzz peaches, at a specified price, "for prompt shipment." Orchard promptly shipped 500 bushels, but by mistake shipped No. 2 Royal Fuzz peaches instead of No. 1. The error in shipment was caused by the negligence of Orchard''s shipping clerk. Which of the following best states Fruitko''s rights and duties upon delivery of the peaches?', 'Orchard''s shipment of the peaches was a counteroffer and Fruitko can refuse to accept them.', 'Orchard''s shipment of the peaches was a counteroffer but, since peaches are perishable, Fruitko, if it does not want to accept them, must reship the peaches to Orchard in order to mitigate Orchard''s losses.', 'Fruitko must accept the peaches because a contract was formed when Orchard shipped them.', 'Although a contract was formed when Orchard shipped the peaches, Fruitko does not have to accept them.', 'D', 'A contract is formed when an offer is made and accepted, and the agreement is supported by consideration. Marquardt v. Perry, 200 P.3d 1126, 1129 (Colo.App.2008).  Acceptance of an offer is generally defined as words or conduct that, when objectively viewed, manifests an intent to accept an offer. Id. A person who, with knowledge of an offer''s terms, voluntarily takes the benefits of the offered services without objection is deemed to have accepted the offer and formed a contract. Restatement (Second), Contracts § 69.', 'mbe_343', 0, '141'),
('mbe_787', 'mbe', '787', '564', '1991-July', 'TORTS', '38', '', 'Doe negligently caused a fire in his house, and the house burned to the ground. As a result, the sun streamed into Peter''s yard next door, which previously had been shaded by Doe''s house. The sunshine destroyed some delicate and valuable trees in Peter''s yard that could grow only in the shade. Peter has brought a negligence action against Doe for the loss of Peter''s trees. Doe has moved to dismiss the complaint. The best argument in support of this motion would be that', 'Doe''s negligence was not the active cause of the loss of Peter''s trees.', 'Doe''s duty to avoid the risks created by a fire did not encompass the risk that sunshine would damage Peter''s trees.', 'the loss of the trees was not a natural and probable consequence of Doe''s negligence.', 'Peter suffered a purely economic loss, which is not compensable in a negligence action.', 'B', 'Proximate cause is the cause that “ ‘ “in natural and continuous sequence, unbroken by an efficient intervening cause, produces the injury and without which the injury would not have occurred, the injury being the natural and probable consequence of the wrongful act.” ’ ” Yount v. Deibert, 282 Kan. 619, 624-25, 147 P.3d 1065 (2006). Individuals are not responsible for all possible consequences arising from their negligence—just those that are probable according to ordinary and usual experience. Hale v. Brown, 287 Kan. 320, 322, 197 P.3d 438 (2008).', 'mbe_835', 0, '38')
